def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    """
    CSV metnini satır sonu ve alan ayırıcılara göre ayrıştırır.

    csv modülünü kullanmaz.
    """
    if not text:
        return []

    # Satırları \r\n veya \n ile böl, sondaki bir satır sonu yok sayılır
    lines = _split_lines(text)

    result = []
    for line in lines:
        if line == "":
            result.append([""])
        else:
            result.append(_parse_line(line, delimiter))

    return result


def _split_lines(text: str) -> list[str]:
    """Metni \\r\\n veya \\n ile ayır, sondaki bir satır sonunu at."""
    if not text:
        return []

    lines = []
    start = 0
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
            lines.append(text[start:i])
            i += 2
            start = i
        elif text[i] == '\n':
            lines.append(text[start:i])
            i += 1
            start = i
        else:
            i += 1

    # Eğer metin \n veya \r\n ile bitiyorsa, lines'ın son elemanı "" olur.
    # Onu at.
    if lines and (text.endswith('\n') or text.endswith('\r\n')):
        if lines[-1] == "":
            lines = lines[:-1]

    return lines


def _parse_line(line: str, delimiter: str) -> list[str]:
    """Tek bir CSV satırını alanlarına ayır."""
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            break

        char = line[i]

        if char == '"':
            # Tırnaklı alan başlangıcı
            field, i = _parse_quoted_field(line, i, delimiter)
            fields.append(field)
            # i, kapanan tırnaktan sonraki pozisyonda
            if i < n:
                if line[i] == delimiter:
                    i += 1
                    continue
                elif line[i] == '\n' or line[i] == '\r':
                    break
                else:
                    raise ValueError(
                        f'Kapanan tırnaktan sonra {line[i]!r} karakteri olamaz, index {i}'
                    )
            else:
                break
        else:
            # Tırnaksız alan
            field, i = _parse_unquoted_field(line, i, delimiter)
            fields.append(field)
            if i < n:
                if line[i] == delimiter:
                    i += 1
                    continue
                elif line[i] == '\n' or line[i] == '\r':
                    break
                else:
                    raise ValueError(
                        f'Geçersiz karakter: {line[i]!r} at index {i}'
                    )
            else:
                break

    if not fields:
        fields.append("")

    return fields


def _parse_quoted_field(line: str, start: int, delimiter: str) -> tuple[str, int]:
    """
    Çift tırnakla başlayan bir alanı ayrıştır.

    start index'i açan tırnağa işaret eder.
    (field_content, i) döndürür; i, kapanan tırnaktan sonraki pozisyondur.
    """
    i = start + 1  # Açan tırnağı atla
    field = []
    n = len(line)

    while i < n:
        char = line[i]

        if char == '"':
            # Kapanan tırnak olabilir
            # Sonraki karakteri kontrol et
            if i + 1 < n:
                next_char = line[i + 1]
                if next_char == '"':
                    # "" -> tek " karakteri
                    field.append('"')
                    i += 2
                elif next_char == delimiter:
                    # Kapanan tırnak, ardından ayırıcı
                    i += 1  # Kapanan tırnağı atla
                    return ''.join(field), i
                elif next_char == '\r' or next_char == '\n':
                    # Kapanan tırnak, ardından satır sonu (\r\n olabilir)
                    # \r\n ise \r'i de atla
                    if next_char == '\r' and i + 2 < n and line[i + 2] == '\n':
                        i += 3
                    else:
                        i += 1
                    return ''.join(field), i
                else:
                    raise ValueError(
                        f'Kapanan tırnaktan sonra {next_char!r} karakteri olamaz, index {i + 1}'
                    )
            else:
                # Satır sonu: kapanan tırnak, satırın sonu
                return ''.join(field), i + 1
        else:
            field.append(char)
            i += 1

    # Döngüden sızdık: kapanan tırnak bulunamadı
    raise ValueError("Kapanan tırnak bulunamadı")


def _parse_unquoted_field(line: str, start: int, delimiter: str) -> tuple[str, int]:
    """
    Tırnaksız bir alanı ayrıştır.

    start index'i alanın başına işaret eder.
    (field_content, i) döndürür; i, alan bittikten sonraki pozisyondur.
    """
    i = start
    n = len(line)
    field = []

    while i < n:
        char = line[i]
        if char == delimiter:
            # Ayırıcı, alan bitti
            return ''.join(field), i
        elif char == '\r' or char == '\n':
            # Satır sonu, alan bitti
            return ''.join(field), i
        else:
            field.append(char)
            i += 1

    # Satır sonu
    return ''.join(field), i

